async function refresh(){try{user=await api('auth/me');if(!user.is_admin&&user.permissions.length===1&&user.permissions[0]==='ngh_reschedule'){view='ngh';return nghView()}data=await api('dashboard');if(user.role==='warehouse'){report={};ops={};statusOptions={po:[],invoice:[]}}else if(user.is_admin||user.permissions.includes('reports_view')){[report,ops,statusOptions]=await Promise.all([api('reports'),api('reports/operations'),api('status-options')])}else{report={};ops={};statusOptions=await api('status-options')}if(user.is_admin)users=await api('auth/users');asnAssignments=user.role==='warehouse'?[]:await api('asn-assignments');warehouseAssignments=await api('warehouse-assignments');if(user.role==='warehouse')view='tasks';else if(!user.is_admin&&view==='admin')view='control';await loadProblemSummary();render()}catch(e){if(e.message==='Sign in required')loginView();else toast(e.message)}}function go(x){if(x==='problems'){searchAll='';openProblemsOnly=true;x='search'}else if(x==='search'){openProblemsOnly=false}view=x==='tasks'&&user?.is_admin?'open':x;selectedPO=null;render();window.scrollTo({top:0,behavior:'instant'})}function render(){if(!user)return loginView();if(view==='merge')return shell(mergeForm(),tr('mergePDF'));if(view==='control')return controlView();if(view==='search')return allPOView();if(view==='ngh')return nghView();if(view==='recent')return specialPOView('recent');if(view==='open'){poView();showNextNumber();return}if(view==='inventory')return inventoryView();if(view==='reports')return reportView();if(view==='imports')return importsView();if(view==='tasks')return tasksView();return adminView()}
function loginView(reset=false){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.getElementById('app').innerHTML=`<div class="login"><div class="brand" style="justify-content:center;margin-bottom:20px"><div class="brand-icon">S</div><h1>Sial Logistics</h1></div><div class="card"><h3>${reset?tr('forgot'):tr('signIn')}</h3><form class="form one" onsubmit="${reset?'requestReset':'login'}(event)">${reset?field('email','Email','email','required'):field('username',tr('user'),'text','required')+field('password',tr('password'),'password','required')}<button class="primary">${reset?tr('sendReset'):tr('signIn')}</button></form><p><button class="secondary" onclick="loginView(${!reset})">${reset?tr('signIn'):tr('forgot')}</button></p></div></div>`}async function login(e){e.preventDefault();try{await api('auth/login','POST',Object.fromEntries(new FormData(e.target)));await refresh()}catch(x){toast(x.message)}}async function logout(){await api('auth/logout','POST',{});user=null;loginView()}async function requestReset(e){e.preventDefault();try{await api('auth/reset-request','POST',Object.fromEntries(new FormData(e.target)));toast('Check your email for a reset link.')}catch(x){toast(x.message)}}function toggleLang(){lang=lang==='en'?'ar':'en';localStorage.setItem('sial-lang',lang);render()}
