let openProblemsOnly=false;
function poSearchResults(){
  const query=searchAll.trim();
  const openProblems=new Set(problemData.problems.filter(p=>p.status!=='resolved').map(p=>p.po_id));
  const ps=(data.pos||[]).filter(po=>po.number.includes(query)&&(!openProblemsOnly||openProblems.has(po.id)));
  return ps.slice(0,100).map(p=>`<article class="po-row summary-row"><div class="po-main"><button class="po-link" onclick="openPO(${p.id})">${esc(p.number)}</button><div>${esc(p.region||'')} · ${st(p.status)}${p.archived?' · '+bilingual('Archived','مؤرشف'):''}</div></div><div>${fmt(p.delivered_qty||0)} delivered · ${fmt(p.remaining_qty||0)} outstanding</div><button class="secondary" onclick="openPO(${p.id})">${tr('details')}</button></article>`).join('') || `<p class="empty">${tr('noRows')}</p>`;
}
