function specialPOView(which){let ps=(data.pos||[]).filter(p=>which==='ngh'?p.is_ngh:p.added_from_pdf).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));shell(`<div class="po-list">${ps.map(p=>`<article class="po-row summary-row"><div class="po-main"><button class="po-link" onclick="openPO(${p.id})">${esc(p.number)}</button><div>${esc(poAddress(p))}</div></div><div>${st(p.status)} · ${esc(p.due_date||'')}</div><button class="secondary" onclick="openPO(${p.id})">${tr('details')}</button></article>`).join('')}</div>`,tr(which))}
