function stockShortages(orders){
  if(!user.is_admin && !(can('inventory_edit') || can('invoice_edit')))return '';
  const active=new Set(orders.map(po=>po.id));
  const months=new Map();
  const available=new Map((data.stock||[]).map(x=>[x.code,Math.max(0,x.free)]));
  for(const line of data.lines||[]){
    if(!active.has(line.po_id))continue;
    const month=/^\d{4}-\d{2}/.exec(line.due_date||'')?.[0]||'—';
    if(!months.has(month))months.set(month,new Map());
    const demand=months.get(month);
    demand.set(line.item_code,(demand.get(line.item_code)||0)+Math.max(0,line.outstanding_qty-line.reserved_qty));
  }
  const short=[];
  for(const month of [...months.keys()].sort()){
    for(const [code,needed] of months.get(month)){
      const free=available.get(code)||0;
      available.set(code,Math.max(0,free-needed));
      if(needed>free)short.push({month,code,needed,free,missing:needed-free});
    }
  }
  const title=bilingual('Monthly inventory shortages','نقص المخزون الشهري');
  if(!short.length)return `<section class="card compact"><h3>${title}</h3>${bilingual('Free stock covers current outstanding demand.','يغطي المخزون الحر الطلب القائم.')}</section>`;
  return `<details class="card compact shortage-strip"><summary><strong>${title}</strong> · ${fmt(new Set(short.map(x=>x.code)).size)} ${tr('item')} · ${fmt(new Set(short.map(x=>x.month)).size)} ${bilingual('months','أشهر')}</summary>${table([bilingual('Due month','شهر الاستحقاق'),tr('item'),bilingual('Required (pcs)','المطلوب (قطعة)'),bilingual('Free (pcs)','المتاح (قطعة)'),bilingual('Short (pcs)','النقص (قطعة)')],short.map(x=>`<tr><td>${esc(x.month)}</td><td>${esc(x.code)}</td><td>${fmt(x.needed)}</td><td>${fmt(x.free)}</td><td><strong>${fmt(x.missing)}</strong></td></tr>`))}</details>`;
}
