function controlView(){
 const pos=(data.pos||[]).filter(p=>p.is_outstanding),urgent=data.urgent||[],reminders=data.reminders||[],submitted=asnAssignments.filter(x=>x.status==='submitted'),warehouse=warehouseAssignments.filter(x=>x.status==='open');
 const metrics=report.metrics||{};
 const overview=[
   ['outstanding',tr('outstanding'),fmt(pos.length)],
   ['urgent',tr('urgent'),fmt(new Set(urgent.map(x=>x.po_id)).size)],
   ['reminders',tr('reminders'),fmt(new Set(reminders.map(x=>x.po_id)).size)]
 ];
 if(!user.is_admin && can('accounting_edit') && metrics.all_po_value!==undefined){
   overview.unshift(['all',bilingual('Total PO value','إجمالي قيمة الأوامر'),money(metrics.all_po_value)+' SAR']);
 }
 const stats=`<div class="stats">${overview.map(([key,label,value])=>`<button class="stat kpi" onclick="showOverviewRecords('${key}')"><span>${esc(label)}</span><strong>${esc(value)}</strong></button>`).join('')}</div>`;
 const recordIds=new Set((overviewFilter==='urgent'?urgent:reminders).map(row=>row.po_id));
 const records=(data.pos||[]).filter(p=>overviewFilter==='all'||(overviewFilter==='paid'?p.paid_amount>0:recordIds.has(p.id)));
 const rows=list=>{let grouped=new Map();for(const x of list){if(!grouped.has(x.po_id))grouped.set(x.po_id,{...x,items:[]});grouped.get(x.po_id).items.push(`${x.item_code}: ${fmt(x.ordered_qty||0)} pcs`)}return [...grouped.values()].slice(0,12).map(x=>`<div class="alert-row"><div><strong>${esc(x.number)}</strong><small>${esc(x.region||'—')} · ${esc(x.items.join(' · '))} · ${esc(x.due_date)}</small></div><button class="secondary" onclick="openPO(${x.po_id})">${tr('details')}</button></div>`).join('')||`<p class="empty">${tr('noRows')}</p>`};
 const regions=regionalChart(pos);
 const selected=(priorityTab==='urgent'?urgent:reminders).filter(r=>!priorityRegion||r.region===priorityRegion);
 const regionSelect=select('priority-region',tr('region'),choices([['',tr('allRegions')],...[...new Set(pos.map(p=>p.region).filter(Boolean))].sort().map(r=>[r,r])],priorityRegion),'onchange="priorityRegion=this.value;controlView()"');
 const actions=`<div class="ops-actions">${paymentIntake()}<button class="secondary" onclick="go('open')">${tr('outstandingPOs')}</button>${can('imports_apply')?`<button class="secondary" onclick="go('imports')">${tr('imports')}</button>`:''}</div>`;
 const chart=`<section class="card"><h3>${bilingual('Pending by region','المستحق حسب المنطقة')}</h3><div class="region-chart">${regions}</div></section>`;
 const queue=`<section class="card"><div class="queue-head"><h3>${bilingual('Delivery priorities','أولويات التسليم')}</h3>${regionSelect}</div>${tabs([['urgent',tr('urgent')],['reminders',tr('reminders')]],priorityTab,'selectPriority')}${rows(selected)}</section>`;
 shell(`<div class="ops-dashboard">${stats}${actions}${stockShortages(pos)}${overviewRecords(records)}<div class="priority-layout">${chart}${queue}</div>${dashboardUpdates()}</div>`,tr('control'));
}
let poReturnView='open';
function returnFromPO(){go(poReturnView)}
function openPO(id){if(selectedPO===null)poReturnView=view;selectedPO=Number(id);view='open';render();window.scrollTo({top:0,behavior:'instant'})}
function filteredPOs(){return (data.pos||[]).filter(p=>(!regionFilter||p.region===regionFilter)&&(poFilter==='archive'?p.archived:poFilter==='all'?!p.archived:poFilter==='delivered'?!p.archived&&['delivered','gr_issued'].includes(p.status):!p.archived&&p.is_outstanding)).filter(p=>!poSearch||[p.number,p.region,p.customer,p.customer_po].some(v=>String(v||'').toLowerCase().includes(poSearch.toLowerCase()))).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')||a.number.localeCompare(b.number))}
function togglePOSelection(id,checked){if(checked)selectedIds.add(id);else selectedIds.delete(id);let count=document.getElementById('selection-count');if(count)count.textContent=selectedIds.size}
function toggleAllPOs(checked){for(let p of filteredPOs()){if(checked)selectedIds.add(p.id);else selectedIds.delete(p.id)}render()}
function updatePOSearch(el){let n=el.selectionStart;poSearch=el.value;render();let next=document.querySelector('input[name=search]');if(next){next.focus();next.setSelectionRange(n,n)}}
Object.assign(EN,{deliveredPOs:'Delivered POs'});
Object.assign(AR,{deliveredPOs:'أوامر الشراء المسلّمة'});
function reassignControl(task){
  if(!user.is_admin||!['open','in_progress','returned','submitted'].includes(task.status))return '';
  const options=users.filter(u=>u.active&&(u.role==='warehouse')===(task.task_type==='warehouse_dispatch'));
  return `<label>Reassign<select onchange="reassignTask(${task.id},this.value)">${choices([['','Select user'],...options.map(u=>[u.username,u.username])])}</select></label>`;
}
async function reassignTask(id,name){
  if(!name)return;
  try{await api('tasks/'+id+'/reassign','POST',{assigned_to:name});await refresh()}catch(e){toast(e.message)}
}
function poView(){
  const p=(data.pos||[]).find(x=>x.id===selectedPO);
  if(p){shell(`<div class="detail-top"><button class="secondary" onclick="returnFromPO()">${bilingual('Back','رجوع')}</button><span class="pill">${st(p.status)}</span></div><div class="po-focus"><section>${user.role==='warehouse'?'':poDetails(p)}</section><aside>${poDocumentPanel(p)}</aside></div>`,`${tr('po')} ${p.number}`,p.region||'');showNextNumber();return}
  const pos=filteredPOs(),regions=[...new Set((data.regional_rows||[]).map(x=>x.region).filter(Boolean))].sort();
  for(const id of [...selectedIds])if(!pos.some(p=>p.id===id))selectedIds.delete(id);
  const filters=`<div class="card compact po-filters">${field('search','Search PO / customer / customer PO','search',`value="${esc(poSearch)}" oninput="updatePOSearch(this)"`)}${select('region',tr('region'),choices([['',tr('allRegions')],...regions.map(x=>[x,x])],regionFilter),'onchange="regionFilter=this.value;selectedIds.clear();render()"')}${select('stage',tr('status'),choices([['outstanding',tr('allOutstanding')],['delivered',st('delivered')],['all',tr('active')],['archive',tr('paidArchive')]],poFilter),'onchange="poFilter=this.value;selectedIds.clear();render()"')}<span class="pill">${fmt(pos.length)} POs</span></div>`;
  const byPO=new Map();for(const r of data.regional_rows||[]){if(!byPO.has(r.po_number))byPO.set(r.po_number,[]);byPO.get(r.po_number).push(r)}
  const cards=pos.map(x=>{let regional=byPO.get(x.number)||[],lines=(data.lines||[]).filter(l=>l.po_number===x.number),parts=regional.length?regional.map(r=>[r.item_text,Number(String(r.left_qty||r.planned_qty||'0').replaceAll(',','')),r.due_date]).filter(r=>r[1]>0):lines.map(l=>[l.item_code,l.quantity,l.due_date]);let nextDue=parts.map(r=>String(r[2]||'').slice(0,10)).filter(Boolean).sort()[0]||x.due_date||'';let assigned=(data.assigned_invoice_numbers||[]).find(n=>n.po_id===x.id)?.number;return `<article class="po-row ${x.urgent?'po-urgent':''}"><label class="po-check"><input type="checkbox" ${selectedIds.has(x.id)?'checked':''} onchange="togglePOSelection(${x.id},this.checked)"><span class="sr-only">Select ${esc(x.number)}</span></label><div class="po-main"><button class="po-link" onclick="openPO(${x.id})">${esc(x.number)}</button><div class="po-meta">${esc(x.region||'—')} · ${esc(x.address||x.customer||'—')}</div><div class="po-summary"><span>Unbooked: <strong>${fmt(x.unbooked_qty??x.remaining_qty??0)} pcs</strong></span><span>Next due: <strong>${esc(nextDue||'—')}</strong></span></div><div class="po-tags">${x.urgent?'<span class="pill danger">🚨 Overdue</span>':''}<span class="pill">${st(x.status)}</span>${assigned?`<span class="pill">${esc(assigned)}</span>`:''}</div></div><div class="po-items">${parts.slice(0,2).map(([code,quantity,due])=>`<div><strong>${esc(code||'—')}</strong><span>${esc(quantity||'—')} pcs · ${esc(String(due||'—').slice(0,10))}</span></div>`).join('')}${parts.length>2?`<small>+${parts.length-2} more schedules in Details</small>`:''}</div><div class="po-actions"><button class="primary" onclick="openPO(${x.id})">${tr('details')}</button></div></article>`}).join('');
  const assignment=user?.is_admin&&poFilter==='outstanding'?`<div class="card compact"><h3>Assign selected POs</h3><div class="assignment-form"><span class="pill"><span id="selection-count">${selectedIds.size}</span> ${tr('selected')}</span><form class="assignment-form" onsubmit="assignASN(event)">${select('assigned_to',tr('assignTo'),choices([['','Select user'],...users.filter(x=>x.active&&!x.is_admin).map(x=>[x.username,x.username])]),'required')}<button class="primary">${tr('assignASN')}</button></form><form class="assignment-form" onsubmit="assignWarehouse(event)">${select('assigned_to','Warehouse user',choices([['','Select user'],...users.filter(x=>x.active&&x.role==='warehouse').map(x=>[x.username,x.username])]),'required')}<button class="secondary">Assign dispatch</button></form></div></div>`:'';
  shell(filters+assignment+shipmentTracking()+`<div class="po-list">${cards||`<div class="card empty">${tr('noRows')}</div>`}</div>`,tr('outstandingPOs'),'Select a PO to see its complete record and files.');
}
async function assignWarehouse(e){e.preventDefault();if(!selectedIds.size)return toast('Select at least one PO');let f=e.target;if(!confirm(`Assign ${selectedIds.size} POs to warehouse?`))return;try{await api('warehouse-assignments','POST',{po_ids:[...selectedIds],assigned_to:f.assigned_to.value});selectedIds.clear();await refresh();toast('Warehouse assignments created')}catch(x){toast(x.message)}}
function poDocumentPanel(p){let docs=(data.documents||[]).filter(d=>d.po_id===p.id);return `<details class="card doc-panel"><summary>${bilingual('Related files','المستندات')} (${fmt(docs.length)})</summary>${(can('pos_edit')||can('merge_pdfs')||asnAssignments.some(t=>t.po_id===p.id&&t.assigned_to===user.username))?`<form class="form one" onsubmit="uploadRelated(event,${p.id})">${select('document_type','File type',choices(['PO','MRR','RCV','Rejection Form','GR','ASN','Invoice','Odoo Invoice','Nupco Proforma','Nupco Invoice','Delivery Note','Other'].filter(x=>x!=='MRR'||!p.number.startsWith('4300')&&!p.number.startsWith('4600')).map(x=>[x,x])))}<input type="file" name="file" accept=".pdf,.png,.jpg,.jpeg,.webp,.txt,.docx,.xlsx" required><button class="primary">Upload file</button></form>${(can('pos_view')||can('pos_edit')||can('merge_pdfs')||asnAssignments.some(t=>t.po_id===p.id))?`<button class="secondary" onclick="mergeInvoicePackage(${p.id})">Merge invoice package</button>`:''}`:''}<div class="doc-list">${docs.length?docs.map(d=>`<div class="doc-entry"><div><small>${esc(d.document_type||'PO')}</small><strong>${esc(d.filename)}</strong></div><div class="actions"><a class="button secondary" target="_blank" rel="noopener" href="/api/documents/${d.id}/view">View</a><a class="button secondary" href="/api/documents/${d.id}">${tr('download')}</a></div></div>`).join(''):`<p class="empty">No files attached to this PO yet.</p>`}</div></details>`}
async function uploadRelated(e,id){e.preventDefault();let fd=new FormData(e.target);try{let j=await api(`pos/${id}/documents/upload`,'POST',fd);await refresh();toast(j.duplicate?'File already attached':'File attached')}catch(x){toast(x.message)}}
async function assignASN(e){e.preventDefault();if(!selectedIds.size)return toast('Select at least one PO');let f=e.target;if(!f.assigned_to.value)return toast(tr('noAssignee'));let ids=[...selectedIds];try{let j=await api('asn-assignments','POST',{po_ids:ids,assigned_to:f.assigned_to.value});selectedIds.clear();await refresh();toast(j.assignments.map(x=>`${x.po_number}: ${x.invoice_number}`).join(' · '))}catch(x){toast(x.message)}}
function poDetails(p){let lines=(data.lines||[]).filter(x=>x.po_number===p.number),invoices=(data.invoices||[]).filter(x=>x.po_id===p.id),issues=(data.issues||[]).filter(x=>x.po_id===p.id),docs=(data.documents||[]).filter(x=>x.po_id===p.id);let details=`<div class="card"><div class="details po-facts">${[[tr('region'),p.region||'—'],[tr('address'),poAddress(p)||'—'],...(p.value==null?[]:[[tr('value'),money(p.value)]]),...(p.invoice_status&&(p.invoice_status!=='rcv_needed'||invoices.length||['delivered','gr_issued'].includes(p.status))?[[tr('invoiceStage'),st(p.invoice_status)]]:[]),...(p.due_date?[[tr('due'),p.due_date]]:[]),...(p.source_invoice_reference?[[tr('sourceInvoice'),p.source_invoice_reference]]:[]),...(p.source_remarks?[[tr('sourceRemarks'),p.source_remarks]]:[]),...(p.customer?[['Customer',p.customer]]:[]),...((p.is_ngh||p.kind==='marketplace')&&p.customer_po?[['Customer PO',p.customer_po]]:[]),...(p.asn_number?[['ASN #',p.asn_number]]:[]),...(p.asn_date?[['ASN date',p.asn_date]]:[]),...(p.asn_link?[['ASN URL',p.asn_link]]:[]),...(p.po_created_at?[['Created',p.po_created_at]]:[])].map(([k,v])=>`<div class="detail"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><h3>${tr('item')}</h3>${table(['#',tr('item'),tr('quantity'),tr('boxes'),tr('pallets'),tr('due'),bilingual('Remaining (pcs)','المتبقي (قطعة)')],lines.map(x=>`<tr><td>${esc(x.line_no)}</td><td class="code">${esc(x.item_code)}</td><td>${fmt(x.quantity)}</td><td>${Math.ceil(x.quantity/x.pcs_per_box)}</td><td>${x.boxes_per_pallet?Math.ceil(x.quantity/x.pcs_per_box/x.boxes_per_pallet):'—'}</td><td>${esc(x.due_date)}</td><td>${x.outstanding_qty==null?'—':fmt(x.outstanding_qty)}</td></tr>`))}</div>`;let statusForm=`<div class="card"><h3>${tr('status')}</h3><form class="form" onsubmit="savePOStatus(event,${p.id})">${select('status',tr('status'),choices((statusOptions.po||[]).map(x=>[x,st(x)]),p.status))}${field('reason',tr('reason'))}${field('asn_number','ASN #','text',`value="${esc(p.asn_number||'')}"`)}${field('asn_date','ASN '+tr('date'),'date',`value="${esc(p.asn_date||'')}"`)}${field('asn_link','ASN URL','url',`value="${esc(p.asn_link||'')}"`)}<label class="full file-input">GR / ASN PDF<input type="file" name="file" accept=".pdf"></label><div class="full actions"><button class="primary">${tr('save')}</button><span class="hint">GR: PDF required. ASN Rejected: PDF or N/A. Reopen delivered PO: admin and reason required.</span></div></form></div>`;let stageForm=`<div class="card"><h3>${tr('invoiceStage')}</h3><form class="form" onsubmit="saveInvoiceStage(event,${p.id})">${select('status',tr('invoiceStage'),choices((statusOptions.invoice||[]).filter(x=>!['paid','partially_paid'].includes(x)).map(x=>[x,st(x)]),p.invoice_status))}${field('reason',tr('reason'))}<button class="primary">${tr('save')}</button></form></div>`;let marketplaceForm=p.kind==='marketplace'?`<div class="card"><h3>${tr('marketplaceStage')}</h3><form class="form" onsubmit="saveMarketplaceStage(event,${p.id})">${select('status',tr('marketplaceStage'),choices([['delivered',st('delivered')],['rcv_returned',st('rcv_returned')]],p.marketplace_status))}${field('reason',tr('reason'))}<button class="primary">${tr('save')}</button></form></div>`:'';let invoicePanel=`<div class="card"><h3>${tr('bookInvoice')}</h3><p class="hint">${tr('nextNumber')}: <strong id="next-number">…</strong>${p.ordered_qty<=p.delivered_qty?' · '+tr('alreadyDelivered'):''}</p><form onsubmit="bookInvoice(event,${p.id})" class="form"><div>${field('number',tr('invoiceNumber'),'text','required')}</div>${field('value',tr('invoiceValue'),'number','min="0" step="0.01"')}<div class="full">${lines.map(x=>`<div class="invoice-line"><label>${esc(x.line_no)} · ${esc(x.item_code)}</label>${select('batch_'+x.id,tr('batch'),choices([['','—'],...(data.batches||[]).filter(b=>b.item_code===x.item_code).map(b=>[b.id,`${b.batch_no} (${fmt(b.quantity)})`])]))}${field('qty_'+x.id,tr('quantity'),'number','min="0" placeholder="0"')}</div>`).join('')}</div><div class="full actions"><button class="primary" ${p.ordered_qty<=p.delivered_qty||p.archived?'disabled':''}>${tr('bookInvoice')}</button></div></form><h3 style="margin-top:25px">${tr('invoice')}</h3>${table([tr('invoiceNumber'),tr('quantity'),tr('status'),'Action'],invoices.map(i=>`<tr><td class="code">${esc(i.number)}</td><td>${fmt(i.quantity)}</td><td>${st(i.status)}</td><td>${invoiceNext(i)}</td></tr>`))}</div>`;let docsPanel=`<div class="card"><h3>${tr('documents')}</h3>${docs.length?docs.map(d=>`<div class="list-row"><span>${esc(d.filename)}</span><a class="button secondary" href="/api/documents/${d.id}">${tr('download')}</a></div>`).join(''):`<p class="muted">${tr('noRows')}</p>`}</div>`;let issuePanel=`<div class="card"><h3>${tr('issue')}</h3><form class="form" onsubmit="addIssue(event,${p.id})">${select('type',tr('problemType'),choices(['Stock shortage','Technical','Delivery','ASN','Payment','Other'].map(x=>[x,x])))}${field('ticket_no',tr('ticket'))}<label class="full">${tr('description')}<textarea name="description" required></textarea></label><button class="primary">${tr('addIssue')}</button></form>${issues.length?table([tr('problemType'),tr('ticket'),tr('description')],issues.map(x=>`<tr><td>${esc(x.type)}</td><td>${esc(x.ticket_no)}</td><td>${esc(x.description)}</td></tr>`)):''}</div>`;return details+(can('pos_edit')?invoices.filter(i=>i.status==='dispatched').map(i=>`<button class="secondary" onclick="returnShipment(this,${p.id},${i.id})">Return shipment · ${esc(i.number)}</button>`).join(''):'')+shipmentHistory(p)+poProblemHistory(p)+`<details class="card"><summary>${bilingual('Update PO','تحديث أمر الشراء')}</summary><div class="grid">${can('pos_edit')?statusForm:''}${can('invoice_edit')&&((p.invoice_status&&!['rcv_needed','paid','partially_paid'].includes(p.invoice_status))||invoices.length)?stageForm:''}${can('pos_edit')?marketplaceForm:''}${user.is_admin?invoicePanel:''}${can('issue_edit')?issuePanel:''}</div></details>`}
function invoiceNext(i){const map={booked:'dispatched',dispatched:'delivered',delivered:'gr_issued',gr_issued:'uploaded'};return map[i.status]?`<button class="secondary" onclick="advanceInvoice(${i.id},'${map[i.status]}')">${st(map[i.status])}</button>`:'—'}
async function advanceInvoice(id,status){if(!confirm(`${tr('confirm')}: ${st(status)}?`))return;try{await api(`invoices/${id}/status`,'PATCH',{status,confirmed:true});await refresh();toast(tr('save'))}catch(e){toast(e.message)}}async function savePOStatus(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;let f=new FormData(e.target);f.set('confirmed','true');if(!f.get('file')?.name)f.delete('file');try{await api(`pos/${id}/operational-status`,'POST',f);await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function saveInvoiceStage(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;try{await api(`pos/${id}/invoice-stage`,'PATCH',{...Object.fromEntries(new FormData(e.target)),confirmed:true});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function saveMarketplaceStage(e,id){e.preventDefault();if(!confirm(tr('confirm')+'?'))return;try{await api(`pos/${id}/marketplace-stage`,'PATCH',{...Object.fromEntries(new FormData(e.target)),confirmed:true});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function addIssue(e,id){e.preventDefault();try{await api('issues','POST',{...Object.fromEntries(new FormData(e.target)),po_id:id});await refresh();toast(tr('save'))}catch(x){toast(x.message)}}async function bookInvoice(e,id){e.preventDefault();let f=e.target,lines=(data.lines||[]).filter(x=>x.po_number===(data.pos||[]).find(p=>p.id===id)?.number),entries=[];for(let l of lines){let qty=Number(f.elements['qty_'+l.id]?.value||0),batch=Number(f.elements['batch_'+l.id]?.value||0);if(qty>0){if(!batch)return toast('Choose a batch for every booked quantity');entries.push({po_line_id:l.id,batch_id:batch,quantity:qty})}}if(!entries.length)return toast('Enter at least one quantity');if(!confirm(tr('confirm')+'?'))return;try{await api('invoices','POST',{po_id:id,number:f.elements.number.value,value:Number(f.elements.value.value||0),lines:entries});await refresh();toast(tr('save'))}catch(x){if(x.detail?.invoice_id&&confirm(`${x.message}\nTransfer the existing booked invoice to this PO?`)){try{await api(`invoices/${x.detail.invoice_id}/transfer`,'POST',{target_po_id:id,confirmed:true});await refresh()}catch(y){toast(y.message)}}else toast(x.message)}}
async function showNextNumber(){let p=(data.pos||[]).find(x=>x.id===selectedPO),node=document.getElementById('next-number');if(!p||!node)return;try{let j=await api(`invoices/next-number?po_id=${p.id}`);node.textContent=j.next_number;let input=document.querySelector('input[name=number]');if(input&&!input.value)input.value=j.next_number}catch(e){node.textContent='—'}}
function inventoryView(){let stock=data.stock||[],batches=data.batches||[];let top=`<div class="card"><h3>${tr('startingStock')}</h3><p class="hint">${tr('stockHelp')}</p><form class="form" onsubmit="previewStock(event)"><label class="file-input full">${tr('stockWorkbook')}<input name="file" type="file" accept=".xlsx" required></label><button class="primary">${tr('preview')}</button></form><div id="stock-preview"></div></div>`;let inventory=`<div class="card"><h3>${tr('inventory')}</h3>${table([tr('item'),'Total (pcs)','Booked (pcs)','Free (pcs)','Boxes in stock','Pallets in stock'],stock.map(x=>`<tr><td class="code"><button class="po-link" onclick="inventorySelected='${esc(x.code)}';render()">${esc(x.code)}</button></td><td>${fmt(x.physical)}</td><td>${fmt(x.booked)}</td><td><strong>${fmt(x.free)}</strong></td><td>${x.pcs_per_box?fmt(Math.ceil(x.physical/x.pcs_per_box)):0}</td><td>${x.pcs_per_box&&x.boxes_per_pallet?fmt(Math.ceil(x.physical/x.pcs_per_box/x.boxes_per_pallet)):0}</td></tr>`))}</div><div class="card"><h3>${tr('batch')}</h3>${select('batch_item',tr('item'),choices([['','All items'],...stock.map(x=>[x.code,x.code])],inventorySelected),'onchange="inventorySelected=this.value;render()"')}${table([tr('item'),tr('batch'),tr('quantity'),tr('free'),tr('mfg'),tr('expiry')],batches.filter(x=>!inventorySelected||x.item_code===inventorySelected).map(x=>`<tr><td>${esc(x.item_code)}</td><td class="code">${esc(x.batch_no)}</td><td>${fmt(x.quantity)}</td><td>${fmt(x.free_quantity)}</td><td>${esc(x.mfg_date)}</td><td>${esc(x.expiry_date)}</td></tr>`))}</div>`;shell(stockInsight(stock)+inventory+(can('inventory_edit')?`<details class="card"><summary>Import starting stock</summary>${top}</details>`:' '),tr('inventory'))}
