function importsView(){
 const choicesList=[['new',bilingual('New PO','أمر جديد')],['document',bilingual('Upload Document','رفع مستند')]];
 if(isOwner())choicesList.push(['excel',bilingual('Sync Excel','مزامنة إكسل')]);

 let body='';
 if(uploadTab==='document')body=documentIntake();
 else if(uploadTab==='excel'&&isOwner()){
 const types=[['due_region','Due and Region'],['payment','NUPCO Payment File'],['inventory','Inventory · زاريس'],['masterlist','PO Masterlist'],['sial_formatted','Sial PO Report']];
 const custom=['payment','inventory'].includes(sheetKind);
 body=`<div class="card"><form class="form" onsubmit="${custom?'syncSpecial(event)':'previewSeed(event)'}">${select('kind',tr('workbookType'),choices(types,sheetKind),'onchange="sheetKind=this.value;syncNotice=String();importsView()"')}${sheetKind==='inventory'?field('counted_at',bilingual('Warehouse count time','وقت الجرد'),'datetime-local','required'):''}<label class="file-input full">Excel<input name="file" type="file" accept=".xlsx" required></label><button class="primary">${custom?bilingual('Sync','مزامنة'):tr('preview')}</button></form><div id="seed-preview"></div><p role="status">${esc(syncNotice)}</p></div>`;
 }else if(uploadTab==='merge'&&can('merge_pdfs'))body=mergeForm();
 else body=`<div class="card"><h3>${bilingual('New PO','أمر جديد')}</h3><p class="hint">${tr('pdfHelp')}</p><form class="form" onsubmit="previewPDFs(event)"><label class="file-input full">${tr('chooseFiles')}<input type="file" name="files" accept=".pdf" multiple required></label><button class="primary">${tr('preview')}</button></form><div id="pdf-preview"></div></div>`;
 shell(tabs(choicesList,uploadTab,'selectUploadTab')+body,tr('imports'));
}
async function syncSpecial(e){
 e.preventDefault();const form=e.target,fd=new FormData(form);
 if(sheetKind==='inventory')fd.set('counted_at',new Date(form.counted_at.value).toISOString());
 try{const r=await api(sheetKind==='inventory'?'admin/sync-inventory':'payment-advice','POST',fd);
 syncNotice=sheetKind==='inventory'?`${r.changed} batches updated. ${r.conflicts.join(' · ')}`:`${r.posted} payments posted`;
 if(r.batch_id)lastAdviceBatch=r.batch_id;await refresh();
 }catch(err){toast(err.message)}
}

