function accessChecks(account={}){
 const existing=(account.permissions||'').split(',');
 return '<fieldset class="access-checks full"><legend>'+bilingual('Access','الصلاحيات')+'</legend>'+accessOptions.map(([key,en,ar])=>`<label class="check"><input type="checkbox" name="${key==='is_admin'?key:'permission'}" value="${key}" ${(key==='is_admin'?account.is_admin:existing.includes(key))?'checked':''}>${bilingual(en,ar)}</label>`).join('')+'</fieldset>';
}
function adminView(){if(!user?.is_admin){shell(`<div class="card"><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></div>`,tr('admin'));return}shell(`<div class="grid"><div class="card"><h3>${tr('createUser')}</h3><form class="form" onsubmit="createUser(event)">${field('username',tr('user'),'text','required')}${field('password',tr('password'),'password','minlength="12" required')}${field('email','Email','email')}${select('role','Role',choices([['staff','Staff'],['warehouse','Warehouse'],['accountant','Accountant']]))}${accessChecks()}<button class="primary">${tr('createUser')}</button></form></div><div class="card"><h3>${tr('users')}</h3><div id="user-list"></div><button class="secondary" onclick="loadUsers()">Refresh</button></div></div><div class="grid"><details class="card"><summary>${tr('customStatuses')}</summary><p class="hint">Core workflow statuses must remain in the list. Add custom codes separated by commas.</p><form class="form one" onsubmit="saveStatuses(event)">${select('group',tr('status'),choices([['po',tr('status')],['invoice',tr('invoiceStage')]]),'onchange="document.querySelector(\'[name=options]\').value=statusOptions[this.value].join(\', \')"')}<label>Codes<textarea name="options">${esc((statusOptions.po||[]).join(', '))}</textarea></label><button class="primary">${tr('save')}</button></form></details><details class="card"><summary>${tr('changePassword')}</summary><form class="form" onsubmit="changePassword(event)">${field('old_password',tr('currentPassword'),'password','required')}${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('changePassword')}</button></form></details></div><div class="card"><h3>${bilingual('Backups','النسخ الاحتياطية')}</h3><div class="actions"><button class="secondary" onclick="loadBackups()">${tr('backup')}</button><button class="danger" onclick="resetAllPOs()">${tr('resetPOs')}</button><button class="danger" onclick="deleteBackups(false)">Delete selected backups</button><button class="danger" onclick="deleteBackups(true)">Delete all backups</button></div><div id="backup-list"></div></div>`,tr('admin'));loadUsers();loadBackups()}
async function loadBackups(){try{let b=await api('admin/backups');backups=b.backups||b;let node=document.getElementById('backup-list');if(node)node.innerHTML=table([tr('date'),tr('details'),''],backups.map(x=>`<tr><td>${esc(x.created_at)}</td><td>${esc(x.label)}</td><td><input type="checkbox" class="backup-check" value="${esc(x.id)}"><a class="button secondary" href="/api/admin/backups/${esc(x.id)}">${tr('download')}</a> <button class="secondary" onclick="restoreBackup('${esc(x.id)}')">${tr('restore')}</button></td></tr>`))}catch(x){toast(x.message)}}
async function resetAllPOs(){try{let preview=await api('admin/reset-preview');let phrase=prompt(`This deletes ${preview.pos} POs, ${preview.invoices} invoices, ${preview.linked_tasks} linked tasks and all PO history. A backup is saved first. Type RESET ALL PURCHASE ORDERS to continue.`);if(phrase!=='RESET ALL PURCHASE ORDERS')return;let j=await api('admin/reset-pos','POST',{phrase});selectedPO=null;selectedIds.clear();await refresh();toast(`PO reset complete. Backup ${j.backup_id}`)}catch(x){toast(x.message)}}
async function restoreBackup(backup_id){let phrase=prompt(`Restore backup ${backup_id}? Current data will be saved first. Type RESTORE DATABASE to continue.`);if(phrase!=='RESTORE DATABASE')return;try{await api('admin/restore-backup','POST',{backup_id,phrase});await refresh();toast(tr('restore'))}catch(x){toast(x.message)}}
async function changePassword(e){e.preventDefault();try{await api('auth/password','POST',Object.fromEntries(new FormData(e.target)));user=null;loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}async function createUser(e){e.preventDefault();let f=e.target,body={username:f.username.value,password:f.password.value,email:f.email.value,role:f.role.value,is_admin:f.is_admin.checked,permissions:[...f.querySelectorAll('[name=permission]:checked')].map(x=>x.value)};try{await api('auth/users','POST',body);await loadUsers();f.reset();toast(tr('save'))}catch(x){toast(x.message)}}async function loadUsers(){try{users=await api('auth/users');let node=document.getElementById('user-list');if(!node)return;node.innerHTML=`<div class="user-cards">${users.map(x=>`<section class="user-card"><div class="user-card-head"><div><strong>${esc(x.username)}</strong><small>${esc(x.username==='admin'?'Main admin':x.is_admin?tr('assistantAdmin'):x.role||'Staff')} · ${x.active?'Active':'Inactive'}</small></div></div><div class="actions"><button class="secondary" onclick="editUser(${x.id})">Edit access</button>${x.username==='admin'?'':`<button class="danger" onclick="deleteUser(${x.id})">Delete</button>`}</div><div id="edit-${x.id}"></div><details class="reset-user"><summary>Reset password</summary><form onsubmit="resetUserPassword(event,${x.id})"><label>New password<input name="password" type="password" minlength="12" autocomplete="new-password" required></label><label class="check"><input type="checkbox" onchange="this.form.password.type=this.checked?'text':'password'">Show new password</label><button class="secondary">Save new password</button></form></details></section>`).join('')}</div>`}catch(x){toast(x.message)}}
function editUser(id){
 const account=users.find(u=>u.id===id),host=document.getElementById('edit-'+id);
 if(!account||!host)return;
 if(host.children.length){host.replaceChildren();return}
 const owner=account.username==='admin';
 host.innerHTML=`<form class="form" onsubmit="saveAccess(event,${id})">${field('username',tr('user'),'text',`value="${esc(account.username)}" required ${owner?'readonly':''}`)}${field('email','Email','email',`value="${esc(account.email)}"`)}${owner?'':select('role','Role',choices([['staff','Staff'],['accountant','Accountant'],['warehouse','Warehouse']],account.role))+accessChecks(account)+`<label class="check"><input type="checkbox" name="active" ${account.active?'checked':''}>Active</label>`}<button class="primary">${tr('save')}</button></form>`;
}
async function saveAccess(e,id){
 e.preventDefault();const f=new FormData(e.target),account=users.find(u=>u.id===id);
 const body={username:f.get('username'),email:f.get('email')};
 if(account.username!=='admin'){
 const legacy=account.permissions.split(',').filter(k=>k&&!accessOptions.some(([key])=>key===k));
 Object.assign(body,{role:f.get('role'),active:f.has('active'),is_admin:f.has('is_admin'),permissions:[...legacy,...f.getAll('permission')]});
 }
 try{await api('auth/users/'+id,'PATCH',body);await loadUsers();toast(tr('save'))}catch(err){toast(err.message)}
}

async function resetUserPassword(e,id){e.preventDefault();let form=e.target,password=form.elements.password.value;if(!password)return;try{await api(`auth/users/${id}`,'PATCH',{password});form.reset();toast('Password reset');await loadUsers()}catch(err){toast(err.message)}}
async function deleteUser(id){if(!confirm('Delete this account? Assigned work will be unassigned and history retained.'))return;try{await api(`auth/users/${id}`,'DELETE');await loadUsers();toast('Account deleted')}catch(e){toast(e.message)}}
async function saveStatuses(e){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));try{await api('status-options','PUT',{group:x.group,options:x.options.split(',').map(y=>y.trim())});statusOptions=await api('status-options');render();toast(tr('save'))}catch(y){toast(y.message)}}
if(new URLSearchParams(location.search).has('reset')){let token=new URLSearchParams(location.search).get('reset');document.getElementById('app').innerHTML=`<div class="login card"><h3>${tr('newPassword')}</h3><form onsubmit="finishReset(event)">${field('new_password',tr('newPassword'),'password','minlength="12" required')}<button class="primary">${tr('save')}</button></form></div>`;window.finishReset=async e=>{e.preventDefault();try{await api('auth/reset-confirm','POST',{token,new_password:e.target.new_password.value});history.replaceState(null,'','/');loginView();toast(tr('signIn'))}catch(x){toast(x.message)}}}else refresh();

async function deleteBackups(all=false){let ids=all?['*']:[...document.querySelectorAll('.backup-check:checked')].map(x=>x.value);if(!ids.length)return toast('Select backups');if(!confirm('Permanently delete '+(all?'ALL backups':ids.length+' selected backups')+'?'))return;try{await api('admin/backups/delete','POST',{ids,phrase:'DELETE SELECTED BACKUPS'});await loadBackups();toast('Backups deleted')}catch(e){toast(e.message)}}

async function savePayment(e,id){e.preventDefault();let f=e.target,x=Object.fromEntries(new FormData(f));x.amount_sar=Number(x.amount_sar);if(!confirm('Record payment of SAR '+x.amount_sar+'?'))return;try{await api(`pos/${id}/payment`,'POST',x);await refresh();toast('Payment saved')}catch(e){toast(e.message)}}async function rescheduleLine(e,id){e.preventDefault();let x=Object.fromEntries(new FormData(e.target));try{await api(`po-lines/${id}/reschedule`,'POST',x);await refresh();toast('Due date updated')}catch(e){toast(e.message)}}

async function mergeInvoicePackage(id){if(!confirm('Merge the required PO and invoice documents?'))return;try{let x=await api(`pos/${id}/documents/merge`,'POST',{});await refresh();toast(x.filename+' ready')}catch(e){toast(e.message)}}

Object.assign(EN,{problems:'PO Problems Center'});
Object.assign(AR,{problems:'مركز مشكلات أوامر الشراء'});

function dashboardUpdates(){
 const recent=(data.pos||[]).filter(p=>p.added_from_pdf).sort((a,b)=>b.id-a.id).slice(0,5);
 const alerts=(data.shipment_history||[]).filter(e=>e.status==='due_rescheduled').slice(0,8);
 return (recent.length?`<section class="card"><h3>${tr('recent')}</h3>${recent.map(p=>`<button class="po-link" onclick="openPO(${p.id})">${esc(p.number)}</button>`).join(' · ')}</section>`:'')+
 (alerts.length?`<section class="card"><h3>${bilingual('NGH rescheduling alerts','تنبيهات إعادة الجدولة')}</h3>${alerts.map(e=>`<p>${esc(e.reason)} · ${esc(e.actor)}</p>`).join('')}</section>`:'');
}
let nghRegion='';
let nghTab='attention';
function selectNghTab(tab){nghTab=tab;nghView()}
async function nghView(){
 try{
 const [records,changes]=await Promise.all([api('ngh-schedule'),api('ngh-schedule/updates')]);if(view!=='ngh')return;
 const attention=r=>r.days_to_due!=null&&r.days_to_due<=14;
 const regions=[...new Set([...records,...changes].map(r=>r.region||'—'))].sort();
 const matches=r=>!nghRegion||(r.region||'—')===nghRegion;
 const queue=records.filter(matches).filter(attention);
 const count=new Set(queue.map(r=>r.number)).size;
 const options=[['attention',bilingual('Needs Attention','تحتاج متابعة')+' · '+count],['all',bilingual('All NGH POs','كل أوامر الحرس')],['updates',bilingual('Updates','التحديثات')]];
 const heads=[tr('po'),bilingual('Customer No.','رقم أمر العميل'),...(!nghRegion?[tr('region')]:[]),tr('item'),bilingual('Remaining (pcs)','المتبقي (قطعة)'),tr('due'),''];
 const list=(nghTab==='attention'?queue:records.filter(matches)).sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999'));
 const content=nghTab==='updates'?table([tr('po'),tr('date'),bilingual('Updated by','حدّثه'),tr('details')],changes.filter(matches).map(e=>`<tr><td>${esc(e.number)}</td><td>${esc(e.created_at)}</td><td>${esc(e.username)}</td><td>${esc(e.reason)}</td></tr>`)):
 table(heads,list.map(r=>`<tr><td><strong>${esc(r.number)}</strong></td><td>${esc(r.customer_po||'—')}</td>${nghRegion?'':'<td>'+esc(r.region||'—')+'</td>'}<td>${esc(r.item)}</td><td>${fmt(r.remaining)}</td><td>${esc(r.due_date)}</td><td><details><summary>${bilingual('Reschedule','إعادة جدولة')}</summary><form onsubmit="rescheduleLine(event,${r.line_id})"><input type="date" aria-label="${tr('due')}" required name="due_date" value="${esc(r.due_date)}"><button>${tr('save')}</button></form></details></td></tr>`));
 shell(tabs(options,nghTab,'selectNghTab')+select('region',tr('region'),choices([['',tr('allRegions')],...regions.map(r=>[r,r])],nghRegion),'onchange="nghRegion=this.value;nghView()"')+content,tr('ngh'));
 }catch(e){toast(e.message)}
}

async function returnShipment(button,po,invoice){
 try{
 const lines=(await api('pos/'+po+'/dispatch-lines')).filter(x=>x.invoice_id===invoice);
 if(!lines.length)throw Error('No dispatched quantities available');
 const form=document.createElement('form');form.className='form';
 const docs=(data.documents||[]).filter(d=>d.po_id===po);
 form.innerHTML=select('mode','Return quantity',choices([['complete','Complete shipment'],['partial','Partial shipment']]))+
 lines.map(l=>`<label class="return-part" hidden>${esc(l.item_code)} · ${esc(l.batch_no)} · ${fmt(l.quantity)} pcs<input type="number" min="0" max="${l.quantity}" name="line_${l.id}" value="0"></label>`).join('')+
 select('document','Rejection form',choices([['','No form'],...docs.map(d=>[d.id,d.filename])]))+
 '<label class="return-part" hidden>New invoice number (optional)<input name="new_invoice"></label><button class="primary">Record return</button>';
 form.elements.mode.onchange=()=>form.querySelectorAll('.return-part').forEach(el=>el.hidden=form.elements.mode.value!=='partial');
 form.onsubmit=async e=>{e.preventDefault();try{
 const partial=form.elements.mode.value==='partial';
 await api('pos/'+po+'/dispatch-return/'+invoice,'POST',{complete:!partial,expected:Object.fromEntries(lines.map(l=>[l.id,l.quantity])),quantities:Object.fromEntries(lines.map(l=>[l.id,Number(form.elements['line_'+l.id].value)])),replacement_invoice:partial?form.elements.new_invoice.value:'',rejection_document:Number(form.elements.document.value)||null});
 await refresh();toast('Returned quantities reopened');
 }catch(err){toast(err.message)}};
 button.replaceWith(form);
 }catch(err){toast(err.message)}
}

